head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > E > onviewchange]<br/>컴포넌트에서 사용자의 조작에 의해 입력값이 변경된 후 포커스가 해제될때 발생합니다.",
    "validation" : [
        "컴포넌트에서 사용자의 조작에 의해 입력값이 변경된 후 포커스가 해제될때 발생합니다.",
        "스크립트에서 setValue() 메소드로 입력값을 변경한 경우 onviewchange 이벤트가 발생하지 않습니다.",
        "info 파라미터로 변경된 입력값에 대한 정보가 객체로 전달됩니다.",
        "info.oldValue 속성값으로 변경되기 전 입력값을 ioFormat 속성에 설정된 포맷에 맞게 갖습니다.",
        "ioFormat 속성을 설정하지 않으면 info.oldValue 속성값으로 calendarValueType 속성값에 맞게 'yyyyMMddHHmmSS' 포맷이 잘려서 적용됩니다.",
        "info.newValue 속성값으로 변경된 후 입력값을 ioFormat 속성에 설정된 포맷에 맞게 갖습니다.",
        "ioFormat 속성을 설정하지 않으면 info.newValue 속성값으로 calendarValueType 속성값에 맞게 'yyyyMMddHHmmSS' 포맷이 잘려서 적용됩니다.",
        "입력값에 변경이 없으면 onviewchange 이벤트는 발생하지 않습니다.",
        "컴포넌트의 날짜 편집 영역에서 입력값을 변경한 후 Enter 키 입력 시 포커스가 해제되며 onviewchange 이벤트가 발생합니다.",
        "컴포넌트의 날짜 편집 영역에서 입력값을 변경한 후 팝업 달력을 표시할때도 onviewchange 이벤트가 발생합니다.",
        "팝업 달력에서 선택한 날짜가 컴포넌트에 적용될때도 onviewchange 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onviewchange"])

    // comp 생성 함수 호출    
    $c.gcm.createBasicInputCalendar('', eList);  
}



scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue);
}



scwin.btn_setValue_onclick = function (e) {
	target1.setValue(par_value.getText());
};
